"""Detect a Cycle in an Undirected Graph — union-find.

An edge whose endpoints already share a root closes a cycle; self-loops and
repeated edges are caught by the same test.

Time: O(E * α(n))   Space: O(n)
"""
from typing import List


class Solution:
    def hasCycleUndirected(self, n: int, edges: List[List[int]]) -> bool:
        parent = list(range(n))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        for u, v in edges:
            ru, rv = find(u), find(v)
            if ru == rv:
                return True
            parent[ru] = rv
        return False
